import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [profile, setProfile] = useState({
    name: "User",
    email: "user@email.com"
  });

  const [alerts, setAlerts] = useState([]);
  const [insights, setInsights] = useState([]);

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("profile"));
    if (saved) setProfile(saved);
  }, []);

  // ✅ NORMALIZE CATEGORY (MAIN FIX)
  const normalizeCategory = (cat) => {
    if (!cat) return "others";

    const c = cat.toLowerCase();

    if (c.includes("food") || c.includes("grocery")) return "food & groceries";
    if (c.includes("bill")) return "bills";
    if (c.includes("shop")) return "shopping";
    if (c.includes("health")) return "health";
    if (c.includes("transport")) return "transport";
    if (c.includes("entertain") || c.includes("misc")) return "other / miscellaneous";

    return "others";
  };

  const detectSource = (txns) => {
    if (!txns.length) return "Not uploaded";

    const text = txns.map(t => t.description?.toLowerCase() || "").join(" ");

    if (text.includes("upi")) return "GPay";
    if (text.includes("hdfc")) return "HDFC Bank";

    return "Bank Statement";
  };

  // ✅ ALERT SYSTEM (FIXED)
  const checkAlerts = (txns) => {
    const user = JSON.parse(localStorage.getItem("user"));
    if (!user) return;

    const limits = JSON.parse(localStorage.getItem(`limits_${user.email}`)) || {};

    let totals = {};

    txns.forEach(t => {
      const cat = normalizeCategory(t.category);
      totals[cat] = (totals[cat] || 0) + Number(t.amount || 0);
    });

    let result = [];

    Object.keys(limits).forEach(cat => {
      const key = normalizeCategory(cat);
      const spent = totals[key] || 0;
      const limit = Number(limits[cat]);

      result.push({
        category: cat,
        spent,
        limit,
        status: spent > limit ? "exceeded" : "ok"
      });
    });

    setAlerts(result);
  };

  // ✅ INSIGHTS (UPDATED)
  const generateInsights = (txns) => {
    if (!txns.length) return;

    let categoryTotals = {};

    txns.forEach(t => {
      const cat = normalizeCategory(t.category);
      categoryTotals[cat] = (categoryTotals[cat] || 0) + Number(t.amount || 0);
    });

    const sorted = Object.entries(categoryTotals)
      .sort((a, b) => b[1] - a[1]);

    let insightsList = [];

    if (sorted.length > 0) {
      insightsList.push(`💸 Highest spending on ${sorted[0][0]}`);
    }

    if (sorted.length > 5) {
      insightsList.push("⚠️ Spending is spread across many categories");
    }

    const exceeded = alerts.filter(a => a.status === "exceeded");
    if (exceeded.length > 0) {
      insightsList.push(`🚨 You exceeded budget in ${exceeded.length} categories`);
    }

    if (sorted.length <= 3) {
      insightsList.push("✅ Your spending is well focused");
    }

    setInsights(insightsList);
  };

  const handleUpload = async () => {
    if (!file) return alert("Select file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:8000/upload-statement/", {
      method: "POST",
      body: formData
    });

    const data = await res.json();
    const txns = data.transactions || [];

    setTransactions(txns);
    setType(detectSource(txns));

    checkAlerts(txns);
    generateInsights(txns);

    const history = JSON.parse(localStorage.getItem("history")) || [];

    history.unshift({
      date: new Date().toLocaleString(),
      type: detectSource(txns),
      count: txns.length,
      transactions: txns
    });

    localStorage.setItem("history", JSON.stringify(history));

    setLoading(false);
  };

  const deleteHistory = (i) => {
    const history = JSON.parse(localStorage.getItem("history")) || [];
    history.splice(i, 1);
    localStorage.setItem("history", JSON.stringify(history));
    setActiveTab("history");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div>
            <div className="logo">FinSight</div>
            <div style={{ fontSize: "13px", color: "#6b7280" }}>
              Personal Expense Intelligence
            </div>
          </div>

          <div className="nav-actions">

            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            <div
              style={{
                width: "40px",
                height: "40px",
                borderRadius: "50%",
                background: "linear-gradient(135deg,#4f6df5,#6a85ff)",
                color: "#fff",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                marginLeft: "12px"
              }}
            >
              {profile.name.charAt(0).toUpperCase()}
            </div>

            <div
              onClick={() => setDarkMode(!darkMode)}
              style={{
                width: "26px",
                height: "26px",
                borderRadius: "50%",
                marginLeft: "12px",
                cursor: "pointer",
                background: "linear-gradient(to right, #ffffff 50%, #9ca3af 50%)",
                border: "1px solid #d1d5db"
              }}
            ></div>

          </div>
        </div>

        <div className="hero">
          <h1>
            Welcome, <span style={{ color: "#4f6df5" }}>{profile.name}</span>
          </h1>
        </div>

        {/* OVERVIEW */}
        {activeTab === "overview" && (
          <>
            <div className="kpi-grid">
              <div className="kpi-card">
                <h4>Statement Source</h4>
                <p>{type || "Not uploaded"}</p>
              </div>

              <div className="kpi-card">
                <h4>Total Transactions</h4>
                <p>{transactions.length}</p>
              </div>

              <div className="kpi-card">
                <h4>Status</h4>
                <p>{transactions.length ? "Processed" : "Waiting"}</p>
              </div>
            </div>

            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input type="file" accept=".pdf" onChange={(e) => setFile(e.target.files[0])} />
                  <button onClick={handleUpload}>
                    {loading ? "Processing..." : "Analyze Statement"}
                  </button>
                </div>
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                {insights.length > 0
                  ? insights.map((i, idx) => <p key={idx}>{i}</p>)
                  : <p>Upload to see insights</p>}
              </div>
            </div>

            {/* ALERTS */}
            {alerts.length > 0 && (
              <div className="card table-card">
                <h3>Budget Alerts</h3>
                {alerts.map((a, i) => (
                  <div key={i}>
                    {a.category}: ₹{a.spent} / ₹{a.limit}
                  </div>
                ))}
              </div>
            )}

            {/* TABLE */}
            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>
                <div style={{ maxHeight: "400px", overflow: "auto" }}>
                  <table style={{ width: "100%" }}>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Category</th>
                        <th>Need/Want</th>
                        <th>Amount</th>
                      </tr>
                    </thead>
                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date}</td>
                          <td>{txn.type}</td>
                          <td>{txn.description}</td>
                          <td>{txn.category}</td>
                          <td>{txn.need_or_want}</td>
                          <td>₹{txn.amount}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}

        {/* HISTORY */}
        {activeTab === "history" && (
          <div className="card table-card">
            <h3>History</h3>

            <table style={{ width: "100%" }}>
              <tbody>
                {(JSON.parse(localStorage.getItem("history")) || []).map((h, i) => (
                  <tr key={i}>
                    <td>{h.date}</td>
                    <td>{h.type}</td>
                    <td>{h.count}</td>
                    <td style={{ display: "flex", justifyContent: "flex-end", gap: "10px" }}>
                      <button onClick={() => {
                        setTransactions(h.transactions);
                        setType(h.type);
                        setActiveTab("overview");
                      }}>View</button>

                      <button onClick={() => deleteHistory(i)}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
